def transform(grid):
    """Extend 5-colored guide bars by repeating the adjacent endpoint motif."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])

    # Horizontal guides: repeat the vertical color sequence below the left end
    # across the guide's columns.
    for r in range(h):
        for left, right in _runs([c for c, v in enumerate(out[r]) if v == 5]):
            if left == right:
                continue
            seq = []
            rr = r + 1
            while rr < h and out[rr][left] not in (0, 5):
                seq.append(out[rr][left])
                rr += 1
            if seq:
                for c in range(left, right + 1):
                    for k, color in enumerate(seq, r + 1):
                        if k < h and out[k][c] == 0:
                            out[k][c] = color

    # Vertical guides: read the rectangular motif immediately to the right of
    # the lower endpoint, then repeat it up the length of the guide.
    for c in range(w):
        for top, bottom in _runs([r for r in range(h) if out[r][c] == 5]):
            if top == bottom or c + 1 >= w:
                continue
            # Motif rows form a contiguous block ending at the bar's bottom.
            start = bottom
            while start > top and out[start - 1][c + 1] not in (0, 5):
                start -= 1
            if out[start][c + 1] in (0, 5):
                continue
            motif = []
            for rr in range(start, bottom + 1):
                row = []
                cc = c + 1
                while cc < w and out[rr][cc] not in (0, 5):
                    row.append(out[rr][cc])
                    cc += 1
                if not row:
                    break
                motif.append(row)
            if not motif:
                continue
            width = min(map(len, motif))
            mh = len(motif)
            for rr in range(top, bottom + 1):
                source_row = motif[(rr - start) % mh]
                for j in range(width):
                    cc = c + 1 + j
                    if out[rr][cc] == 0:
                        out[rr][cc] = source_row[j]
    return out
